import sys, re


def main():
    data = sys.stdin.read().split()
    mode = int(data[0])
    m = int(data[1])
    toks = data[2:2 + m]
    out = []
    for t in toks:
        d = re.sub(r'[^0-9]', '', t)
        L = len(d)
        if mode == 1:
            ok = 13 <= L <= 16
        else:
            ok = False
            if d[:1] == '4' and L in (13, 16):
                ok = True
            elif L == 15 and d[:2] in ('34', '37'):
                ok = True
            elif L == 16 and (51 <= int(d[:2]) <= 55 or 2221 <= int(d[:4]) <= 2720):
                ok = True
        if ok:
            keep_from = L - 4
            seen = 0
            res = []
            for c in t:
                if '0' <= c <= '9':
                    res.append('x' if seen < keep_from else c)
                    seen += 1
                else:
                    res.append(c)
            out.append(''.join(res))
        else:
            out.append(t)
    print(' '.join(out))


